Compatibility shim for loading OpenVLA with transformers >= 5.x.

OpenVLA's prismatic code targets transformers 4.40.1; transformers 5.x removed
``AutoModelForVision2Seq`` and tightened auto-detection so ``model_type=openvla``
is no longer recognized. This module:
  1. Registers ``OpenVLAConfig`` / ``OpenVLAForActionPrediction`` with AutoConfig
     and AutoModelForCausalLM.
  2. Applies the minimal monkey-patches needed for the prismatic ``generate``
     path (SDPA flag, ``tie_weights`` signature, GenerationMixin base).
  3. Provides ``load_openvla_processor(path)`` since AutoImageProcessor in
     transformers 5.x rejects ImageProcessingMixin subclasses that don't
     inherit ``BaseImageProcessor``.

Call ``patch_openvla_for_transformers5()`` before instantiating the model.
"""
import sys

sys.path.insert(0, "/root/autodl-tmp/openvla-repo")

from prismatic.extern.hf.configuration_prismatic import (
    OpenVLAConfig,
    PrismaticConfig,
)
from prismatic.extern.hf.modeling_prismatic import (
    OpenVLAForActionPrediction,
    PrismaticForConditionalGeneration,
)
from prismatic.extern.hf.processing_prismatic import (
    PrismaticImageProcessor,
    PrismaticProcessor,
)
from transformers import (
    AutoConfig,
    AutoModelForCausalLM,
    AutoTokenizer,
    GenerationMixin,
)
from transformers.cache_utils import Cache

_PATCHED = False


def _register_with_auto_factories():
    AutoConfig.register("openvla", OpenVLAConfig, exist_ok=True)
    AutoConfig.register("prismatic", PrismaticConfig, exist_ok=True)
    AutoModelForCausalLM.register(OpenVLAConfig, OpenVLAForActionPrediction, exist_ok=True)
    AutoModelForCausalLM.register(PrismaticConfig, PrismaticForConditionalGeneration, exist_ok=True)


def patch_openvla_for_transformers5():
    """Idempotent compatibility patch — safe to call multiple times."""
    global _PATCHED
    if _PATCHED:
        return
    _PATCHED = True

    PrismaticForConditionalGeneration._supports_sdpa = True
    PrismaticForConditionalGeneration._supports_flash_attn_2 = False

    _orig_tie = PrismaticForConditionalGeneration.tie_weights
    def _patched_tie(self, **kwargs):
        return _orig_tie(self)
    PrismaticForConditionalGeneration.tie_weights = _patched_tie

    if not issubclass(PrismaticForConditionalGeneration, GenerationMixin):
        bases = PrismaticForConditionalGeneration.__bases__
        PrismaticForConditionalGeneration.__bases__ = (bases[0], GenerationMixin) + bases[1:]

    # Fix: transformers 5.x pre-creates an empty DynamicCache before the first
    # forward call. The original prepare_inputs_for_generation checks
    # `past_key_values is not None` to decide whether to truncate input_ids,
    # but an empty DynamicCache is not None — so the prefill step gets only
    # the last token, the image is never processed, and generation fails.
    _orig_prepare = PrismaticForConditionalGeneration.prepare_inputs_for_generation

    def _patched_prepare_inputs(
        self, input_ids=None, past_key_values=None, inputs_embeds=None,
        pixel_values=None, attention_mask=None, **kwargs,
    ):
        has_cached = past_key_values is not None and (
            (isinstance(past_key_values, Cache) and past_key_values.get_seq_length() > 0)
            or (not isinstance(past_key_values, Cache))
        )

        if (input_ids is not None and input_ids.shape[0] > 1) or (
            inputs_embeds is not None and inputs_embeds.shape[0] > 1
        ):
            raise ValueError("Generation with batch size > 1 is not currently supported!")

        if has_cached:
            input_ids = input_ids[:, -1:]

        if inputs_embeds is not None and not has_cached:
            model_inputs = {"input_embeds": inputs_embeds}
        else:
            model_inputs = {"input_ids": input_ids}

        model_inputs.update({
            "attention_mask": attention_mask,
            "pixel_values": pixel_values,
            "past_key_values": past_key_values,
            "use_cache": kwargs.get("use_cache"),
        })
        return model_inputs

    PrismaticForConditionalGeneration.prepare_inputs_for_generation = _patched_prepare_inputs

    _register_with_auto_factories()


def load_openvla_processor(pretrained_path: str) -> PrismaticProcessor:
    """Construct a PrismaticProcessor without going through AutoImageProcessor."""
    image_processor = PrismaticImageProcessor.from_pretrained(pretrained_path)
    tokenizer = AutoTokenizer.from_pretrained(pretrained_path)
    return PrismaticProcessor(image_processor=image_processor, tokenizer=tokenizer)
